    self.full_path = name
    if name == '-':
        self.name = None
        self.size = None
    else:
        self.name = name
        self.size = os.stat(name).st_size
    self.key_type = key_type
    if key_type == self.KEY_STREAM_READABLE:
        self.fp = sys.stdin
        self.full_path = '<STDIN>'
    elif key_type == self.KEY_STREAM_WRITABLE:
        self.fp = sys.stdout
        self.full_path = '<STDOUT>'
    else:
        self.fp = fp

def __init__(self, http_response, response_headers):
    self.http_response = http_response
    self.status = http_response.status
    self[u'RequestId'] = http_response.getheader('x-amzn-requestid')
    if response_headers:
        for header_name, item_name in response_headers:
            self[item_name] = http_response.getheader(header_name)
    if http_response.status != 204: 
        if http_response.getheader('Content-Type') == 'application/json':
            body = json.loads(http_response.read().decode('utf-8'))
            self.update(body)
    size = http_response.getheader('Content-Length', None)
    if size is not None:
        self.size = size

def authorize(self, connection, **kwargs):
    if not getattr(self, '_headers_quoted', False):
        for key in self.headers:
            val = self.headers[key]
            if isinstance(val, six.text_type):
                safe = '!"#$%&\'()*+,/:;<=>?@[\\]^`{|}~ '
                self.headers[key] = quote(val.encode('utf-8'), safe)
        setattr(self, '_headers_quoted', True)

    self.headers['User-Agent'] = UserAgent

    connection._auth_handler.add_auth(self, **kwargs)

    # I'm not sure if this is still needed, now that add_auth is
    # setting the content-length for POST requests.
    if 'Content-Length' not in self.headers:
        if 'Transfer-Encoding' not in self.headers or \
                self.headers['Transfer-Encoding'] != 'chunked':
            self.headers['Content-Length'] = str(len(self.body))

