    grants = []
    for g in self.grants:
        if g.type == 'CanonicalUser':
            u = g.display_name
        elif g.type == 'Group':
            u = g.uri
        else:
            u = g.email_address
        grants.append("%s = %s" % (u, g.permission))
    return "<BucketLoggingStatus: %s/%s (%s)>" % (self.target, self.prefix, ", ".join(grants))

