def generate_url_sigv4(self, expires_in, method, bucket='', key='',
                        headers=None, force_http=False,
                        response_headers=None, version_id=None,
                        iso_date=None):
    path = self.calling_format.build_path_base(bucket, key)
    auth_path = self.calling_format.build_auth_path(bucket, key)
    host = self.calling_format.build_host(self.server_name(), bucket)

    # For presigned URLs we should ignore the port if it's HTTPS
    if host.endswith(':443'):
        host = host[:-4]

    params = {}
    if version_id is not None:
        params['VersionId'] = version_id

    if response_headers is not None:
        params.update(response_headers)

    http_request = self.build_base_http_request(method, path, auth_path,
                                                headers=headers, host=host,
                                                params=params)

    return self._auth_handler.presign(http_request, expires_in,
                                      iso_date=iso_date)

def generate_url(self, expires_in, method, bucket='', key='', headers=None,
                 query_auth=True, force_http=False, response_headers=None,
                 expires_in_absolute=False, version_id=None):
    if self._auth_handler.capability[0] == 'hmac-v4-s3' and query_auth:
        # Handle the special sigv4 case
        return self.generate_url_sigv4(expires_in, method, bucket=bucket,
            key=key, headers=headers, force_http=force_http,
            response_headers=response_headers, version_id=version_id)

    headers = headers or {}
    if expires_in_absolute:
        expires = int(expires_in)
    else:
        expires = int(time.time() + expires_in)
    auth_path = self.calling_format.build_auth_path(bucket, key)
    auth_path = self.get_path(auth_path)
    # optional version_id and response_headers need to be added to
    # the query param list.
    extra_qp = []
    if version_id is not None:
        extra_qp.append("versionId=%s" % version_id)
    if response_headers:
        for k, v in response_headers.items():
            extra_qp.append("%s=%s" % (k, urllib.parse.quote(v)))
    if self.provider.security_token:
        headers['x-amz-security-token'] = self.provider.security_token
    if extra_qp:
        delimiter = '?' if '?' not in auth_path else '&'
        auth_path += delimiter + '&'.join(extra_qp)
    self.calling_format.build_path_base(bucket, key)
    if query_auth and not self.anon:
        c_string = boto.utils.canonical_string(method, auth_path, headers,
                                               expires, self.provider)
        b64_hmac = self._auth_handler.sign_string(c_string)
        encoded_canonical = urllib.parse.quote(b64_hmac, safe='')
        query_part = '?' + self.QueryString % (encoded_canonical, expires,
                                               self.aws_access_key_id)
    else:
        query_part = ''
    if headers:
        hdr_prefix = self.provider.header_prefix
        for k, v in headers.items():
            if k.startswith(hdr_prefix):
                # headers used for sig generation must be
                # included in the url also.
                extra_qp.append("%s=%s" % (k, urllib.parse.quote(v)))
    if extra_qp:
        delimiter = '?' if not query_part else '&'
        query_part += delimiter + '&'.join(extra_qp)
    if force_http:
        protocol = 'http'
        port = 80
    else:
        protocol = self.protocol
        port = self.port
    return self.calling_format.build_url_base(self, protocol,
                                              self.server_name(port),
                                              bucket, key) + query_part

def get_http_connection(self, host, port, is_secure):
    conn = self._pool.get_http_connection(host, port, is_secure)
    if conn is not None:
        return conn
    else:
        return self.new_http_connection(host, port, is_secure)

def skip_proxy(self, host):
    if not self.no_proxy:
        return False

    if self.no_proxy == "*":
        return True

    hostonly = host
    hostonly = host.split(':')[0]

    for name in self.no_proxy.split(','):
        if name and (hostonly.endswith(name) or host.endswith(name)):
            return True

    return False

def get_proxy_auth_header(self):
    auth = encodebytes(self.proxy_user + ':' + self.proxy_pass)
    return {'Proxy-Authorization': 'Basic %s' % auth}

def set_host_header(self, request):
    try:
        request.headers['Host'] = \
            self._auth_handler.host_header(self.host, request)
    except AttributeError:
        request.headers['Host'] = self.host.split(':', 1)[0]

def prefix_proxy_to_path(self, path, host=None):
    path = self.protocol + '://' + (host or self.server_name()) + path
    return path

def build_base_http_request(self, method, path, auth_path,
                            params=None, headers=None, data='', host=None):
    path = self.get_path(path)
    if auth_path is not None:
        auth_path = self.get_path(auth_path)
    if params is None:
        params = {}
    else:
        params = params.copy()
    if headers is None:
        headers = {}
    else:
        headers = headers.copy()
    if self.host_header and not boto.utils.find_matching_headers('host', headers):
        headers['host'] = self.host_header
    host = host or self.host
    if self.use_proxy and not self.skip_proxy(host):
        if not auth_path:
            auth_path = path
        path = self.prefix_proxy_to_path(path, host)
        if self.proxy_user and self.proxy_pass and not self.is_secure:
            # If is_secure, we don't have to set the proxy authentication
            # header here, we did that in the CONNECT to the proxy.
            headers.update(self.get_proxy_auth_header())
    return HTTPRequest(method, self.protocol, host, self.port,
                       path, auth_path, params, headers, data)

def make_request(self, method, path, headers=None, data='', host=None,
                 auth_path=None, sender=None, override_num_retries=None,
                 params=None, retry_handler=None):
    """Makes a request to the server, with stock multiple-retry logic."""
    if params is None:
        params = {}
    http_request = self.build_base_http_request(method, path, auth_path,
                                                params, headers, data, host)
    return self._mexe(http_request, sender, override_num_retries,
                      retry_handler=retry_handler)

def make_request(self, action, params=None, path='/', verb='GET'):
    http_request = self.build_base_http_request(verb, path, None,
                                                params, {}, '',
                                                self.host)
    if action:
        http_request.params['Action'] = action
    if self.APIVersion:
        http_request.params['Version'] = self.APIVersion
    return self._mexe(http_request)

def get_proxy_url_with_auth(self):
    if not self.use_proxy:
        return None

    if self.proxy_user or self.proxy_pass:
        if self.proxy_pass:
            login_info = '%s:%s@' % (self.proxy_user, self.proxy_pass)
        else:
            login_info = '%s@' % self.proxy_user
    else:
        login_info = ''

    return 'http://%s%s:%s' % (login_info, self.proxy, str(self.proxy_port or self.port))

