def get_utf8_value(value):
    if not six.PY2 and isinstance(value, bytes):
        return value

    if not isinstance(value, six.string_types):
        value = six.text_type(value)

    if isinstance(value, six.text_type):
        value = value.encode('utf-8')

    return value

def canonical_query_string(self, http_request):
    # Note that we just do not return an empty string for
    # POST request. Query strings in url are included in canonical
    # query string.
    l = []
    for param in sorted(http_request.params):
        value = boto.utils.get_utf8_value(http_request.params[param])
        l.append('%s=%s' % (urllib.parse.quote(param, safe='-_.~'),
                            urllib.parse.quote(value, safe='-_.~')))
    return '&'.join(l)

def mklist(value):
    if not isinstance(value, list):
        if isinstance(value, tuple):
            value = list(value)
        else:
            value = [value]
    return value

def encode(cls, p, rp, v, label=None):
    if p.name.startswith('_'):
        return
    try:
        mthd = getattr(cls, 'encode_'+p.ptype)
        mthd(p, rp, v, label)
    except AttributeError:
        raise EncoderError('Unknown type: %s' % p.ptype)

def encode_array(cls, p, rp, v, l):
    v = boto.utils.mklist(v)
    if l:
        label = l
    else:
        label = p.name
    label = label + '.%d'
    for i, value in enumerate(v):
        rp[label%(i+1)] = value

def process_filters(self):
    filters = self.args.get('filters', [])
    filter_names = [f['name'] for f in self.Filters]
    unknown_filters = [f for f in filters if f not in filter_names]
    if unknown_filters:
        raise FilterError('Unknown filters: %s' % unknown_filters)
    for i, filter in enumerate(self.Filters):
        name = filter['name']
        if name in filters:
            self.request_params['Filter.%d.Name' % (i+1)] = name
            for j, value in enumerate(boto.utils.mklist(filters[name])):
                Encoder.encode(filter, self.request_params, value,
                               'Filter.%d.Value.%d' % (i+1, j+1))

def do_cli(self):
    if not self.parser:
        self.build_cli_parser()
    self.cli_options, self.cli_args = self.parser.parse_args()
    d = {}
    self.process_standard_options(self.cli_options, self.cli_args, d)
    for param in self.Params:
        if param.long_name:
            p_name = param.long_name.replace('-', '_')
        else:
            p_name = boto.utils.pythonize_name(param.name)
        value = getattr(self.cli_options, p_name)
        if param.ptype == 'file' and value:
            if value == '-':
                value = sys.stdin.read()
            else:
                path = os.path.expanduser(value)
                path = os.path.expandvars(path)
                if os.path.isfile(path):
                    fp = open(path)
                    value = fp.read()
                    fp.close()
                else:
                    self.parser.error('Unable to read file: %s' % path)
        d[p_name] = value
    for arg in self.Args:
        if arg.long_name:
            p_name = arg.long_name.replace('-', '_')
        else:
            p_name = boto.utils.pythonize_name(arg.name)
        value = None
        if arg.cardinality == 1:
            if len(self.cli_args) >= 1:
                value = self.cli_args[0]
        else:
            value = self.cli_args
        d[p_name] = value
    self.args.update(d)
    if hasattr(self.cli_options, 'filter') and self.cli_options.filter:
        d = {}
        for filter in self.cli_options.filter:
            name, value = filter.split('=')
            d[name] = value
        if 'filters' in self.args:
            self.args['filters'].update(d)
        else:
            self.args['filters'] = d
    try:
        response = self.main()
        self.cli_formatter(response)
    except RequiredParamError as e:
        print(e)
        sys.exit(1)
    except self.ServiceClass.ResponseError as err:
        print('Error(%s): %s' % (err.error_code, err.error_message))
        sys.exit(1)
    except boto.roboto.awsqueryservice.NoCredentialsError as err:
        print('Unable to find credentials.')
        sys.exit(1)
    except Exception as e:
        print(e)
        sys.exit(1)

def compute_hash(fp, buf_size=8192, size=None, hash_algorithm=md5):
    hash_obj = hash_algorithm()
    spos = fp.tell()
    if size and size < buf_size:
        s = fp.read(size)
    else:
        s = fp.read(buf_size)
    while s:
        if not isinstance(s, bytes):
            s = s.encode('utf-8')
        hash_obj.update(s)
        if size:
            size -= len(s)
            if size <= 0:
                break
        if size and size < buf_size:
            s = fp.read(size)
        else:
            s = fp.read(buf_size)
    hex_digest = hash_obj.hexdigest()
    base64_digest = encodebytes(hash_obj.digest()).decode('utf-8')
    if base64_digest[-1] == '\n':
        base64_digest = base64_digest[0:-1]
    # data_size based on bytes read.
    data_size = fp.tell() - spos
    fp.seek(spos)
    return (hex_digest, base64_digest, data_size)

def payload(self, http_request):
    body = http_request.body
    # If the body is a file like object, we can use
    # boto.utils.compute_hash, which will avoid reading
    # the entire body into memory.
    if hasattr(body, 'seek') and hasattr(body, 'read'):
        return boto.utils.compute_hash(body, hash_algorithm=sha256)[0]
    elif not isinstance(body, bytes):
        body = body.encode('utf-8')
    return sha256(body).hexdigest()

def _send_file_internal(self, fp, headers=None, cb=None, num_cb=10,
                        query_args=None, chunked_transfer=False, size=None,
                        hash_algs=None):
    provider = self.bucket.connection.provider
    try:
        spos = fp.tell()
    except IOError:
        spos = None
        self.read_from_stream = False

    # If hash_algs is unset and the MD5 hasn't already been computed,
    # default to an MD5 hash_alg to hash the data on-the-fly.
    if hash_algs is None and not self.md5:
        hash_algs = {'md5': md5}
    digesters = dict((alg, hash_algs[alg]()) for alg in hash_algs or {})

    def sender(http_conn, method, path, data, headers):
        # This function is called repeatedly for temporary retries
        # so we must be sure the file pointer is pointing at the
        # start of the data.
        if spos is not None and spos != fp.tell():
            fp.seek(spos)
        elif spos is None and self.read_from_stream:
            # if seek is not supported, and we've read from this
            # stream already, then we need to abort retries to
            # avoid setting bad data.
            raise provider.storage_data_error(
                'Cannot retry failed request. fp does not support seeking.')

        # If the caller explicitly specified host header, tell putrequest
        # not to add a second host header. Similarly for accept-encoding.
        skips = {}
        if boto.utils.find_matching_headers('host', headers):
          skips['skip_host'] = 1
        if boto.utils.find_matching_headers('accept-encoding', headers):
          skips['skip_accept_encoding'] = 1
        http_conn.putrequest(method, path, **skips)
        for key in headers:
            http_conn.putheader(key, headers[key])
        http_conn.endheaders()

        save_debug = self.bucket.connection.debug
        self.bucket.connection.debug = 0
        # If the debuglevel < 4 we don't want to show connection
        # payload, so turn off HTTP connection-level debug output (to
        # be restored below).
        # Use the getattr approach to allow this to work in AppEngine.
        if getattr(http_conn, 'debuglevel', 0) < 4:
            http_conn.set_debuglevel(0)

        data_len = 0
        if cb:
            if size:
                cb_size = size
            elif self.size:
                cb_size = self.size
            else:
                cb_size = 0
            if chunked_transfer and cb_size == 0:
                # For chunked Transfer, we call the cb for every 1MB
                # of data transferred, except when we know size.
                cb_count = (1024 * 1024) / self.BufferSize
            elif num_cb > 1:
                cb_count = int(
                    math.ceil(cb_size / self.BufferSize / (num_cb - 1.0)))
            elif num_cb < 0:
                cb_count = -1
            else:
                cb_count = 0
            i = 0
            cb(data_len, cb_size)

        bytes_togo = size
        if bytes_togo and bytes_togo < self.BufferSize:
            chunk = fp.read(bytes_togo)
        else:
            chunk = fp.read(self.BufferSize)

        if not isinstance(chunk, bytes):
            chunk = chunk.encode('utf-8')

        if spos is None:
            # read at least something from a non-seekable fp.
            self.read_from_stream = True
        while chunk:
            chunk_len = len(chunk)
            data_len += chunk_len
            if chunked_transfer:
                http_conn.send('%x;\r\n' % chunk_len)
                http_conn.send(chunk)
                http_conn.send('\r\n')
            else:
                http_conn.send(chunk)
            for alg in digesters:
                digesters[alg].update(chunk)
            if bytes_togo:
                bytes_togo -= chunk_len
                if bytes_togo <= 0:
                    break
            if cb:
                i += 1
                if i == cb_count or cb_count == -1:
                    cb(data_len, cb_size)
                    i = 0
            if bytes_togo and bytes_togo < self.BufferSize:
                chunk = fp.read(bytes_togo)
            else:
                chunk = fp.read(self.BufferSize)

            if not isinstance(chunk, bytes):
                chunk = chunk.encode('utf-8')

        self.size = data_len

        for alg in digesters:
            self.local_hashes[alg] = digesters[alg].digest()

        if chunked_transfer:
            http_conn.send('0\r\n')
                # http_conn.send("Content-MD5: %s\r\n" % self.base64md5)
            http_conn.send('\r\n')

        if cb and (cb_count <= 1 or i > 0) and data_len > 0:
            cb(data_len, cb_size)

        http_conn.set_debuglevel(save_debug)
        self.bucket.connection.debug = save_debug
        response = http_conn.getresponse()
        body = response.read()

        if not self.should_retry(response, chunked_transfer):
            raise provider.storage_response_error(
                response.status, response.reason, body)

        return response

    if not headers:
        headers = {}
    else:
        headers = headers.copy()
    # Overwrite user-supplied user-agent.
    for header in find_matching_headers('User-Agent', headers):
        del headers[header]
    headers['User-Agent'] = UserAgent
    # If storage_class is None, then a user has not explicitly requested
    # a storage class, so we can assume STANDARD here
    if self._storage_class not in [None, 'STANDARD']:
        headers[provider.storage_class_header] = self.storage_class
    if find_matching_headers('Content-Encoding', headers):
        self.content_encoding = merge_headers_by_name(
            'Content-Encoding', headers)
    if find_matching_headers('Content-Language', headers):
        self.content_language = merge_headers_by_name(
            'Content-Language', headers)
    content_type_headers = find_matching_headers('Content-Type', headers)
    if content_type_headers:
        # Some use cases need to suppress sending of the Content-Type
        # header and depend on the receiving server to set the content
        # type. This can be achieved by setting headers['Content-Type']
        # to None when calling this method.
        if (len(content_type_headers) == 1 and
                headers[content_type_headers[0]] is None):
            # Delete null Content-Type value to skip sending that header.
            del headers[content_type_headers[0]]
        else:
            self.content_type = merge_headers_by_name(
                'Content-Type', headers)
    elif self.path:
        self.content_type = mimetypes.guess_type(self.path)[0]
        if self.content_type is None:
            self.content_type = self.DefaultContentType
        headers['Content-Type'] = self.content_type
    else:
        headers['Content-Type'] = self.content_type
    if self.base64md5:
        headers['Content-MD5'] = self.base64md5
    if chunked_transfer:
        headers['Transfer-Encoding'] = 'chunked'
        #if not self.base64md5:
        #    headers['Trailer'] = "Content-MD5"
    else:
        headers['Content-Length'] = str(self.size)
    # This is terrible. We need a SHA256 of the body for SigV4, but to do
    # the chunked ``sender`` behavior above, the ``fp`` isn't available to
    # the auth mechanism (because closures). Detect if it's SigV4 & embelish
    # while we can before the auth calculations occur.
    if 'hmac-v4-s3' in self.bucket.connection._required_auth_capability():
        kwargs = {'fp': fp, 'hash_algorithm': hashlib.sha256}
        if size is not None:
            kwargs['size'] = size
        headers['_sha256'] = compute_hash(**kwargs)[0]
    headers['Expect'] = '100-Continue'
    headers = boto.utils.merge_meta(headers, self.metadata, provider)
    resp = self.bucket.connection.make_request(
        'PUT',
        self.bucket.name,
        self.name,
        headers,
        sender=sender,
        query_args=query_args
    )
    self.handle_version_headers(resp, force=True)
    self.handle_addl_headers(resp.getheaders())

