def decode(self, value):
    try:
        value = base64.b64decode(value.encode('utf-8')).decode('utf-8')
    except:
        boto.log.warning('Unable to decode message')
        return value
    return value

def decode(self, value):
    try:
        msg = {}
        fp = StringIO(value)
        line = fp.readline()
        while line:
            delim = line.find(':')
            key = line[0:delim]
            value = line[delim+1:].strip()
            msg[key.strip()] = value.strip()
            line = fp.readline()
    except:
        raise SQSDecodeError('Unable to decode message', self)
    return msg

def encode(self, value):
    s = ''
    for item in value.items():
        s = s + '%s: %s\n' % (item[0], item[1])
    return s

def encode_string(cls, p, rp, v, l):
    if l:
        label = l
    else:
        label = p.name
    rp[label] = v

def encode_integer(cls, p, rp, v, l):
    if l:
