        self.kind = None

def __get__(self, obj, objtype):
    value = super(S3KeyProperty, self).__get__(obj, objtype)
    if value:
        if isinstance(value, self.data_type):
            return value
        match = re.match(self.validate_regex, value)
        if match:
            s3 = obj._manager.get_s3_connection()
            bucket = s3.get_bucket(match.group(1), validate=False)
            k = bucket.get_key(match.group(2))
            if not k:
                k = bucket.new_key(match.group(2))
                k.set_contents_from_string("")
            return k
    else:
        return value

def __repr__(self):
    if self.generation and self.metageneration:
        ver_str = '#%s.%s' % (self.generation, self.metageneration)
    else:
        ver_str = ''
    if self.bucket:
        return '<Key: %s,%s%s>' % (self.bucket.name, self.name, ver_str)
    else:
        return '<Key: None,%s%s>' % (self.name, ver_str)

def _key_name(self):
