    :rtype: :class:`boto.file.key.Key`
    :returns: An instance of the newly created key object
    """
    if key_name == '-':
        return Key(self.name, '-', key_type=Key.KEY_STREAM_WRITABLE)
    else:
        dir_name = os.path.dirname(key_name)
