    else:
        volume_id = volume
    return self.ec2.detach_volume(volume_id=volume_id, instance_id=self.instance_id)

def to_dict(self):
    """
    Convert a BatchList object into format required for Layer1.
    """
    d = {}
    for batch in self:
        b = batch.to_dict()
        if b['Keys']:
            d[batch.table.name] = b
    return d

def to_dict(self):
    """
    Convert a BatchWriteList object into format required for Layer1.
    """
    d = {}
    for batch in self:
        table_name, batch_dict = batch.to_dict()
        d[table_name] = batch_dict
    return d

def _queue_unprocessed(self, res):
    if u'UnprocessedKeys' not in res:
        return
    if self.table.name not in res[u'UnprocessedKeys']:
        return

    keys = res[u'UnprocessedKeys'][self.table.name][u'Keys']

    for key in keys:
        h = key[u'HashKeyElement']
        r = key[u'RangeKeyElement'] if u'RangeKeyElement' in key else None
        self.keys.append((h, r))

def update_from_response(self, response):
    """
    Update the state of the Table object based on the response
    data received from Amazon DynamoDB.
    """
    # 'Table' is from a describe_table call.
    if 'Table' in response:
        self._dict.update(response['Table'])
    # 'TableDescription' is from a create_table call.
    elif 'TableDescription' in response:
        self._dict.update(response['TableDescription'])
    if 'KeySchema' in self._dict:
        self._schema = Schema(self._dict['KeySchema'])

def create(cls, hash_key, range_key=None):
    """Convenience method to create a schema object.

    Example usage::

        schema = Schema.create(hash_key=('foo', 'N'))
        schema2 = Schema.create(hash_key=('foo', 'N'),
                                range_key=('bar', 'S'))

    :type hash_key: tuple
    :param hash_key: A tuple of (hash_key_name, hash_key_type)

    :type range_key: tuple
    :param hash_key: A tuple of (range_key_name, range_key_type)

    """
    reconstructed = {
        'HashKeyElement': {
            'AttributeName': hash_key[0],
            'AttributeType': hash_key[1],
        }
    }
    if range_key is not None:
        reconstructed['RangeKeyElement'] = {
            'AttributeName': range_key[0],
            'AttributeType': range_key[1],
        }
    instance = cls(None)
    instance._dict = reconstructed
    return instance

def read_units(self):
    try:
        return self._dict['ProvisionedThroughput']['ReadCapacityUnits']
    except KeyError:
        return None

def write_units(self):
    try:
        return self._dict['ProvisionedThroughput']['WriteCapacityUnits']
    except KeyError:
        return None

def schema(self):
    """
    Returns the schema structure DynamoDB expects.

    Example::

        >>> index.schema()
        {
            'IndexName': 'LastNameIndex',
            'KeySchema': [
                {
                    'AttributeName': 'username',
                    'KeyType': 'HASH',
                },
            ],
            'Projection': {
                'ProjectionType': 'KEYS_ONLY',
            },
            'ProvisionedThroughput': {
                'ReadCapacityUnits': 5,
                'WriteCapacityUnits': 5
            }
        }

    """
    schema_data = super(GlobalBaseIndexField, self).schema()
    schema_data['ProvisionedThroughput'] = {
        'ReadCapacityUnits': int(self.throughput['read']),
        'WriteCapacityUnits': int(self.throughput['write']),
    }
    return schema_data

def __delitem__(self, key):
    """Remove this key from the items"""
    if self._updates is not None:
        self.delete_attribute(key)
    dict.__delitem__(self, key)

def __setitem__(self, key, value):
    """Overrwrite the setter to instead update the _updates
    method so this can act like a normal dict"""
    if self._updates is not None:
        self.put_attribute(key, value)
    dict.__setitem__(self, key, value)

def update(self, throughput=None, global_indexes=None):
    """
    Updates table attributes and global indexes in DynamoDB.

    Optionally accepts a ``throughput`` parameter, which should be a
    dictionary. If provided, it should specify a ``read`` & ``write`` key,
    both of which should have an integer value associated with them.

    Optionally accepts a ``global_indexes`` parameter, which should be a
    dictionary. If provided, it should specify the index name, which is also
    a dict containing a ``read`` & ``write`` key, both of which
    should have an integer value associated with them. If you are writing
    new code, please use ``Table.update_global_secondary_index``.

    Returns ``True`` on success.

    Example::

        # For a read-heavier application...
        >>> users.update(throughput={
        ...     'read': 20,
        ...     'write': 10,
        ... })
        True

        # To also update the global index(es) throughput.
        >>> users.update(throughput={
        ...     'read': 20,
        ...     'write': 10,
        ... },
        ... global_secondary_indexes={
        ...     'TheIndexNameHere': {
        ...         'read': 15,
        ...         'write': 5,
        ...     }
        ... })
        True
    """

    data = None

    if throughput:
        self.throughput = throughput
        data = {
            'ReadCapacityUnits': int(self.throughput['read']),
            'WriteCapacityUnits': int(self.throughput['write']),
        }

    gsi_data = None

    if global_indexes:
        gsi_data = []

        for gsi_name, gsi_throughput in global_indexes.items():
            gsi_data.append({
                "Update": {
                    "IndexName": gsi_name,
                    "ProvisionedThroughput": {
                        "ReadCapacityUnits": int(gsi_throughput['read']),
                        "WriteCapacityUnits": int(gsi_throughput['write']),
                    },
                },
            })

    if throughput or global_indexes:
        self.connection.update_table(
            self.table_name,
            provisioned_throughput=data,
            global_secondary_index_updates=gsi_data,
        )

        return True
    else:
        msg = 'You need to provide either the throughput or the ' \
              'global_indexes to update method'
        boto.log.error(msg)

        return False

def update_global_secondary_index(self, global_indexes):
    """
    Updates a global index(es) in DynamoDB after the table has been created.

    Requires a ``global_indexes`` parameter, which should be a
    dictionary. If provided, it should specify the index name, which is also
    a dict containing a ``read`` & ``write`` key, both of which
    should have an integer value associated with them.

    To update ``global_indexes`` information on the ``Table``, you'll need
    to call ``Table.describe``.

    Returns ``True`` on success.

    Example::

        # To update a global index
        >>> users.update_global_secondary_index(global_indexes={
        ...     'TheIndexNameHere': {
        ...         'read': 15,
        ...         'write': 5,
        ...     }
        ... })
        True

    """

    if global_indexes:
        gsi_data = []

        for gsi_name, gsi_throughput in global_indexes.items():
            gsi_data.append({
                "Update": {
                    "IndexName": gsi_name,
                    "ProvisionedThroughput": {
                        "ReadCapacityUnits": int(gsi_throughput['read']),
                        "WriteCapacityUnits": int(gsi_throughput['write']),
                    },
                },
            })

        self.connection.update_table(
            self.table_name,
            global_secondary_index_updates=gsi_data,
        )
        return True
    else:
        msg = 'You need to provide the global indexes to ' \
              'update_global_secondary_index method'
        boto.log.error(msg)

        return False

