        for slots_var in slots:
            orig_vars.pop(slots_var)
    orig_vars.pop('__dict__', None)
    orig_vars.pop('__weakref__', None)
    return metaclass(cls.__name__, cls.__bases__, orig_vars)

def print_(*args, **kwargs):
    """The new-style print function for Python 2.4 and 2.5."""
    fp = kwargs.pop("file", sys.stdout)
    if fp is None:
        return

    def write(data):
        if not isinstance(data, basestring):
            data = str(data)
        # If the file has an encoding, encode unicode with it.
        if (isinstance(fp, file) and
                isinstance(data, unicode) and
                fp.encoding is not None):
            errors = getattr(fp, "errors", None)
            if errors is None:
                errors = "strict"
            data = data.encode(fp.encoding, errors)
        fp.write(data)
    want_unicode = False
    sep = kwargs.pop("sep", None)
    if sep is not None:
        if isinstance(sep, unicode):
            want_unicode = True
        elif not isinstance(sep, str):
            raise TypeError("sep must be None or a string")
    end = kwargs.pop("end", None)
    if end is not None:
        if isinstance(end, unicode):
            want_unicode = True
        elif not isinstance(end, str):
            raise TypeError("end must be None or a string")
    if kwargs:
        raise TypeError("invalid keyword arguments to print()")
    if not want_unicode:
        for arg in args:
            if isinstance(arg, unicode):
                want_unicode = True
                break
    if want_unicode:
        newline = unicode("\n")
        space = unicode(" ")
    else:
        newline = "\n"
        space = " "
    if sep is None:
        sep = space
    if end is None:
        end = newline
    for i, arg in enumerate(args):
        if i:
            write(sep)
        write(arg)
    write(end)

def _shutdown_threads(self):
    log.debug("Shutting down threads.")
    for thread in self._threads:
        thread.should_continue = False
    for thread in self._threads:
        thread.join()
    log.debug("Threads have exited.")

def _add_work_items_to_queue(self, total_parts, worker_queue, part_size):
    log.debug("Adding work items to queue.")
    for i in range(total_parts):
        worker_queue.put((i, part_size))
    for i in range(self._num_threads):
        worker_queue.put(_END_SENTINEL)

def run(self):
    while self.should_continue:
        try:
            work = self._worker_queue.get(timeout=1)
        except Empty:
            continue
        if work is _END_SENTINEL:
            self._cleanup()
            return
        result = self._process_chunk(work)
        self._result_queue.put(result)
    self._cleanup()

