    """Convert this ResourceRecordSet into XML
    to be saved via the ChangeResourceRecordSetsRequest"""
    changesXML = ""
    for change in self.changes:
        changeParams = {"action": change[0], "record": change[1].to_xml()}
        changesXML += self.ChangeXML % changeParams
    params = {"comment": self.comment, "changes": changesXML}
    return self.ChangeResourceRecordSetsBody % params

def commit(self):
    """Commit this change"""
    if not self.connection:
        import boto
        self.connection = boto.connect_route53()
    return self.connection.change_rrsets(self.hosted_zone_id, self.to_xml())

def __iter__(self):
    """Override the next function to support paging"""
    results = super(ResourceRecordSets, self).__iter__()
    truncated = self.is_truncated
    while results:
        for obj in results:
            yield obj
        if self.is_truncated:
            self.is_truncated = False
            results = self.connection.get_all_rrsets(self.hosted_zone_id, name=self.next_record_name,
                                                     type=self.next_record_type,
                                                     identifier=self.next_record_identifier)
        else:
            results = None
            self.is_truncated = truncated

def get_records(self):
    """
    Return a ResourceRecordsSets for all of the records in this zone.
    """
    return self.route53connection.get_all_rrsets(self.id)

def to_print(self):
    rr = ""
    if self.alias_hosted_zone_id is not None and self.alias_dns_name is not None:
        # Show alias
        rr = 'ALIAS ' + self.alias_hosted_zone_id + ' ' + self.alias_dns_name
        if self.alias_evaluate_target_health is not None:
            rr += ' (EvalTarget %s)' % self.alias_evaluate_target_health
    else:
        # Show resource record(s)
        rr = ",".join(self.resource_records)

    if self.identifier is not None and self.weight is not None:
        rr += ' (WRR id=%s, w=%s)' % (self.identifier, self.weight)
    elif self.identifier is not None and self.region is not None:
        rr += ' (LBR id=%s, region=%s)' % (self.identifier, self.region)
    elif self.identifier is not None and self.failover is not None:
        rr += ' (FAILOVER id=%s, failover=%s)' % (self.identifier, self.failover)

    return rr

def _make_qualified(self, value):
    """
    Ensure passed domain names end in a period (.) character.
    This will usually make a domain fully qualified.
    """
    if type(value) in [list, tuple, set]:
        new_list = []
        for record in value:
            if record and not record[-1] == '.':
                new_list.append("%s." % record)
            else:
                new_list.append(record)
        return new_list
    else:
        value = value.strip()
        if value and not value[-1] == '.':
            value = "%s." % value
        return value

def delete_record(self, record, comment=""):
    """
    Delete one or more records from this Zone.  Returns a Status object.

    :param record: A ResourceRecord (e.g. returned by
       find_records) or list, tuple, or set of ResourceRecords.

    :type comment: str
    :param comment: A comment that will be stored with the change.
    """
    changes = ResourceRecordSets(self.route53connection, self.id, comment)
    if type(record) in [list, tuple, set]:
        for r in record:
            changes.add_change_record("DELETE", r)
    else:
        changes.add_change_record("DELETE", record)
    return Status(self.route53connection, self._commit(changes))

def __next__(self):
    self._offset += 1

    if self._offset >= len(self._results):
        if self._results_left is False:
            raise StopIteration()

        self.fetch_more()

        # It's possible that previous call to ``fetch_more`` may not return
        # anything useful but there may be more results. Loop until we get
        # something back, making sure we guard for no results left.
        while not len(self._results) and self._results_left:
            self.fetch_more()

    if self._offset < len(self._results):
        if self._limit is not None:
            self._limit -= 1

            if self._limit < 0:
                raise StopIteration()

        return self._results[self._offset]
    else:
        raise StopIteration()

def _query(self, limit=None, index=None, reverse=False, consistent=False,
           exclusive_start_key=None, select=None, attributes_to_get=None,
           query_filter=None, conditional_operator=None, **filter_kwargs):
    """
    The internal method that performs the actual queries. Used extensively
    by ``ResultSet`` to perform each (paginated) request.
    """
    kwargs = {
        'limit': limit,
        'index_name': index,
        'consistent_read': consistent,
        'select': select,
        'attributes_to_get': attributes_to_get,
        'conditional_operator': conditional_operator,
    }

    if reverse:
        kwargs['scan_index_forward'] = False

    if exclusive_start_key:
        kwargs['exclusive_start_key'] = {}

        for key, value in exclusive_start_key.items():
            kwargs['exclusive_start_key'][key] = \
                self._dynamizer.encode(value)

    # Convert the filters into something we can actually use.
    kwargs['key_conditions'] = self._build_filters(
        filter_kwargs,
        using=QUERY_OPERATORS
    )

    kwargs['query_filter'] = self._build_filters(
        query_filter,
        using=FILTER_OPERATORS
    )

    raw_results = self.connection.query(
        self.table_name,
        **kwargs
    )
    results = []
    last_key = None

    for raw_item in raw_results.get('Items', []):
        item = Item(self)
        item.load({
            'Item': raw_item,
        })
        results.append(item)

    if raw_results.get('LastEvaluatedKey', None):
        last_key = {}

        for key, value in raw_results['LastEvaluatedKey'].items():
            last_key[key] = self._dynamizer.decode(value)

    return {
        'results': results,
        'last_key': last_key,
    }

def _scan(self, limit=None, exclusive_start_key=None, segment=None,
          total_segments=None, attributes=None, conditional_operator=None,
          **filter_kwargs):
    """
    The internal method that performs the actual scan. Used extensively
    by ``ResultSet`` to perform each (paginated) request.
    """
    kwargs = {
        'limit': limit,
        'segment': segment,
        'total_segments': total_segments,
        'attributes_to_get': attributes,
        'conditional_operator': conditional_operator,
    }

    if exclusive_start_key:
        kwargs['exclusive_start_key'] = {}

        for key, value in exclusive_start_key.items():
            kwargs['exclusive_start_key'][key] = \
                self._dynamizer.encode(value)

    # Convert the filters into something we can actually use.
    kwargs['scan_filter'] = self._build_filters(
        filter_kwargs,
        using=FILTER_OPERATORS
    )

    raw_results = self.connection.scan(
        self.table_name,
        **kwargs
    )
    results = []
    last_key = None

    for raw_item in raw_results.get('Items', []):
        item = Item(self)
        item.load({
            'Item': raw_item,
        })
        results.append(item)

    if raw_results.get('LastEvaluatedKey', None):
        last_key = {}

        for key, value in raw_results['LastEvaluatedKey'].items():
            last_key[key] = self._dynamizer.decode(value)

    return {
        'results': results,
        'last_key': last_key,
    }

def _batch_get(self, keys, consistent=False, attributes=None):
    """
    The internal method that performs the actual batch get. Used extensively
    by ``BatchGetResultSet`` to perform each (paginated) request.
    """
    items = {
        self.table_name: {
            'Keys': [],
        },
    }

    if consistent:
        items[self.table_name]['ConsistentRead'] = True

    if attributes is not None:
        items[self.table_name]['AttributesToGet'] = attributes

    for key_data in keys:
        raw_key = {}

        for key, value in key_data.items():
            raw_key[key] = self._dynamizer.encode(value)

        items[self.table_name]['Keys'].append(raw_key)

    raw_results = self.connection.batch_get_item(request_items=items)
    results = []
    unprocessed_keys = []

    for raw_item in raw_results['Responses'].get(self.table_name, []):
        item = Item(self)
        item.load({
            'Item': raw_item,
        })
        results.append(item)

    raw_unprocessed = raw_results.get('UnprocessedKeys', {}).get(self.table_name, {})

    for raw_key in raw_unprocessed.get('Keys', []):
        py_key = {}

        for key, value in raw_key.items():
            py_key[key] = self._dynamizer.decode(value)

        unprocessed_keys.append(py_key)

    return {
        'results': results,
        # NEVER return a ``last_key``. Just in-case any part of
        # ``ResultSet`` peeks through, since much of the
        # original underlying implementation is based on this key.
        'last_key': None,
        'unprocessed_keys': unprocessed_keys,
    }

def schema(self):
    """
    Returns the schema structure DynamoDB expects.

    Example::

        >>> field.schema()
        {
            'AttributeName': 'username',
            'KeyType': 'HASH',
        }

    """
    return {
        'AttributeName': self.name,
        'KeyType': self.attr_type,
    }

def schema(self):
    """
    Returns the schema structure DynamoDB expects.

    Example::

        >>> index.schema()
        {
            'IndexName': 'LastNameIndex',
            'KeySchema': [
                {
                    'AttributeName': 'username',
                    'KeyType': 'HASH',
                },
            ],
            'Projection': {
                'ProjectionType': 'KEYS_ONLY',
            }
        }

    """
    key_schema = []

    for part in self.parts:
        key_schema.append(part.schema())

    return {
        'IndexName': self.name,
        'KeySchema': key_schema,
        'Projection': {
            'ProjectionType': self.projection_type,
        }
    }

def _introspect_schema(self, raw_schema, raw_attributes=None):
    """
    Given a raw schema structure back from a DynamoDB response, parse
    out & build the high-level Python objects that represent them.
    """
    from boto.dynamodb2.fields import RangeKey
    from boto.dynamodb2.fields import HashKey
    from boto.dynamodb2.types import STRING
    schema = []
    sane_attributes = {}

    if raw_attributes:
        for field in raw_attributes:
            sane_attributes[field['AttributeName']] = field['AttributeType']

    for field in raw_schema:
        data_type = sane_attributes.get(field['AttributeName'], STRING)

        if field['KeyType'] == 'HASH':
            schema.append(
                HashKey(field['AttributeName'], data_type=data_type)
            )
        elif field['KeyType'] == 'RANGE':
            schema.append(
                RangeKey(field['AttributeName'], data_type=data_type)
            )
        else:
            raise exceptions.UnknownSchemaFieldError(
                "%s was seen, but is unknown. Please report this at "
                "https://github.com/boto/boto/issues." % field['KeyType']
            )

    return schema

def _introspect_all_indexes(self, raw_indexes, map_indexes_projection):
    """
    Given a raw index/global index structure back from a DynamoDB response,
    parse out & build the high-level Python objects that represent them.
    """
    indexes = []

    for field in raw_indexes:
        index_klass = map_indexes_projection.get('ALL')
        kwargs = {
            'parts': []
        }

        if field['Projection']['ProjectionType'] == 'ALL':
            index_klass = map_indexes_projection.get('ALL')
        elif field['Projection']['ProjectionType'] == 'KEYS_ONLY':
            index_klass = map_indexes_projection.get('KEYS_ONLY')
        elif field['Projection']['ProjectionType'] == 'INCLUDE':
            index_klass = map_indexes_projection.get('INCLUDE')
            kwargs['includes'] = field['Projection']['NonKeyAttributes']
        else:
            raise exceptions.UnknownIndexFieldError(
                "%s was seen, but is unknown. Please report this at "
                "https://github.com/boto/boto/issues." % \
                field['Projection']['ProjectionType']
            )

        name = field['IndexName']
        kwargs['parts'] = self._introspect_schema(field['KeySchema'], None)
        indexes.append(index_klass(name, **kwargs))

    return indexes

def __init__(self, *args, **kwargs):
    self.includes_fields = kwargs.pop('includes', [])
    super(IncludeIndex, self).__init__(*args, **kwargs)

def __init__(self, *args, **kwargs):
    throughput = kwargs.pop('throughput', None)

    if throughput is not None:
        self.throughput = throughput

    super(GlobalBaseIndexField, self).__init__(*args, **kwargs)

def __init__(self, *args, **kwargs):
    throughput = kwargs.pop('throughput', None)
    IncludeIndex.__init__(self, *args, **kwargs)
    if throughput:
        kwargs['throughput'] = throughput
    GlobalBaseIndexField.__init__(self, *args, **kwargs)

def _encode_keys(self, keys):
    """
    Given a flat Python dictionary of keys/values, converts it into the
    nested dictionary DynamoDB expects.

    Converts::

        {
            'username': 'john',
            'tags': [1, 2, 5],
        }

    ...to...::

        {
            'username': {'S': 'john'},
            'tags': {'NS': ['1', '2', '5']},
        }

    """
    raw_key = {}

    for key, value in keys.items():
        raw_key[key] = self._dynamizer.encode(value)

    return raw_key

def _determine_alterations(self):
    """
    Checks the ``-orig_data`` against the ``_data`` to determine what
    changes to the data are present.

    Returns a dictionary containing the keys ``adds``, ``changes`` &
    ``deletes``, containing the updated data.
    """
    alterations = {
        'adds': {},
        'changes': {},
        'deletes': [],
    }

    orig_keys = set(self._orig_data.keys())
    data_keys = set(self._data.keys())

    # Run through keys we know are in both for changes.
    for key in orig_keys.intersection(data_keys):
        if self._data[key] != self._orig_data[key]:
            if self._is_storable(self._data[key]):
                alterations['changes'][key] = self._data[key]
            else:
                alterations['deletes'].append(key)

    # Run through additions.
    for key in data_keys.difference(orig_keys):
        if self._is_storable(self._data[key]):
            alterations['adds'][key] = self._data[key]

    # Run through deletions.
    for key in orig_keys.difference(data_keys):
        alterations['deletes'].append(key)

    return alterations

def build_expects(self, fields=None):
    """
    Builds up a list of expecations to hand off to DynamoDB on save.

    Largely internal.
    """
    expects = {}

    if fields is None:
        fields = list(self._data.keys()) + list(self._orig_data.keys())

    # Only uniques.
    fields = set(fields)

    for key in fields:
        expects[key] = {
            'Exists': True,
        }
        value = None

        # Check for invalid keys.
        if not key in self._orig_data and not key in self._data:
            raise ValueError("Unknown key %s provided." % key)

        # States:
        # * New field (only in _data)
        # * Unchanged field (in both _data & _orig_data, same data)
        # * Modified field (in both _data & _orig_data, different data)
        # * Deleted field (only in _orig_data)
        orig_value = self._orig_data.get(key, NEWVALUE)
        current_value = self._data.get(key, NEWVALUE)

        if orig_value == current_value:
            # Existing field unchanged.
            value = current_value
        else:
            if key in self._data:
                if not key in self._orig_data:
                    # New field.
                    expects[key]['Exists'] = False
                else:
                    # Existing field modified.
                    value = orig_value
            else:
               # Existing field deleted.
                value = orig_value

        if value is not None:
            expects[key]['Value'] = self._dynamizer.encode(value)

    return expects

def prepare_partial(self):
    """
    Runs through **ONLY** the changed/deleted fields & encodes them to be
    handed off to DynamoDB as part of an ``partial_save`` (``update_item``)
    call.

    Largely internal.
    """
    # This doesn't save on its own. Rather, we prepare the datastructure
    # and hand-off to the table to handle creation/update.
    final_data = {}
    fields = set()
    alterations = self._determine_alterations()

    for key, value in alterations['adds'].items():
        final_data[key] = {
            'Action': 'PUT',
            'Value': self._dynamizer.encode(self._data[key])
        }
        fields.add(key)

    for key, value in alterations['changes'].items():
        final_data[key] = {
            'Action': 'PUT',
            'Value': self._dynamizer.encode(self._data[key])
        }
        fields.add(key)

    for key in alterations['deletes']:
        final_data[key] = {
            'Action': 'DELETE',
        }
        fields.add(key)

    return final_data, fields

def _build_filters(self, filter_kwargs, using=QUERY_OPERATORS):
    """
    An internal method for taking query/scan-style ``**kwargs`` & turning
    them into the raw structure DynamoDB expects for filtering.
    """
    if filter_kwargs is None:
        return

    filters = {}

    for field_and_op, value in filter_kwargs.items():
        field_bits = field_and_op.split('__')
        fieldname = '__'.join(field_bits[:-1])

        try:
            op = using[field_bits[-1]]
        except KeyError:
            raise exceptions.UnknownFilterTypeError(
                "Operator '%s' from '%s' is not recognized." % (
                    field_bits[-1],
                    field_and_op
                )
            )

        lookup = {
            'AttributeValueList': [],
            'ComparisonOperator': op,
        }

        # Special-case the ``NULL/NOT_NULL`` case.
        if field_bits[-1] == 'null':
            del lookup['AttributeValueList']

            if value is False:
                lookup['ComparisonOperator'] = 'NOT_NULL'
            else:
                lookup['ComparisonOperator'] = 'NULL'
        # Special-case the ``BETWEEN`` case.
        elif field_bits[-1] == 'between':
            if len(value) == 2 and isinstance(value, (list, tuple)):
                lookup['AttributeValueList'].append(
                    self._dynamizer.encode(value[0])
                )
                lookup['AttributeValueList'].append(
                    self._dynamizer.encode(value[1])
                )
        # Special-case the ``IN`` case
        elif field_bits[-1] == 'in':
            for val in value:
                lookup['AttributeValueList'].append(self._dynamizer.encode(val))
        else:
            # Fix up the value for encoding, because it was built to only work
            # with ``set``s.
            if isinstance(value, (list, tuple)):
                value = set(value)
            lookup['AttributeValueList'].append(
                self._dynamizer.encode(value)
            )

        # Finally, insert it into the filters.
        filters[fieldname] = lookup

    return filters

def get_keys(self):
    """
    Returns a Python-style dict of the keys/values.

    Largely internal.
    """
    key_fields = self.table.get_key_fields()
    key_data = {}

    for key in key_fields:
        key_data[key] = self[key]

    return key_data

def get_raw_keys(self):
    """
    Returns a DynamoDB-style dict of the keys/values.

    Largely internal.
    """
    raw_key_data = {}

    for key, value in self.get_keys().items():
        raw_key_data[key] = self._dynamizer.encode(value)

    return raw_key_data

def __exit__(self, type, value, traceback):
    if self._to_put or self._to_delete:
        # Flush anything that's left.
        self.flush()

    if self._unprocessed:
        # Finally, handle anything that wasn't processed.
        self.resend_unprocessed()

def put_item(self, data, overwrite=False):
    self._to_put.append(data)

    if self.should_flush():
        self.flush()

def delete_item(self, **kwargs):
    self._to_delete.append(kwargs)

    if self.should_flush():
        self.flush()

def should_flush(self):
    if len(self._to_put) + len(self._to_delete) == 25:
        return True

    return False

def flush(self):
    batch_data = {
        self.table.table_name: [
            # We'll insert data here shortly.
        ],
    }

    for put in self._to_put:
        item = Item(self.table, data=put)
        batch_data[self.table.table_name].append({
            'PutRequest': {
                'Item': item.prepare_full(),
            }
        })

    for delete in self._to_delete:
        batch_data[self.table.table_name].append({
            'DeleteRequest': {
                'Key': self.table._encode_keys(delete),
            }
        })

    resp = self.table.connection.batch_write_item(batch_data)
    self.handle_unprocessed(resp)

    self._to_put = []
    self._to_delete = []
    return True

def _is_storable(self, value):
    # We need to prevent ``None``, empty string & empty set from
    # heading to DDB, but allow false-y values like 0 & False make it.
    if not value:
        if not value in (0, 0.0, False):
            return False

    return True

