def to_xml(self):
    """Convert LifecycleConfig object into XML string representation."""
    s = ['<?xml version="1.0" encoding="UTF-8"?>']
    s.append('<' + LIFECYCLE_CONFIG + '>')
    for rule in self:
        s.append(rule.to_xml())
    s.append('</' + LIFECYCLE_CONFIG + '>')
    return ''.join(s)

def to_xml(self):
    s = '<Rule>'
    if self.id is not None:
        s += '<ID>%s</ID>' % self.id
    s += '<Prefix>%s</Prefix>' % self.prefix
    s += '<Status>%s</Status>' % self.status
    if self.expiration is not None:
        s += self.expiration.to_xml()
    if self.transition is not None:
        s += self.transition.to_xml()
    s += '</Rule>'
    return s

